import {projects} from './projects.8135d600ec1c.mjs';
const t=(lang,tr,en)=>lang==='en'?en:tr;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=(p,l)=>esc(p.title[l==='en'?1:0]);
export function studioDesk(lang){
 const scraps=[
  {src:projects[0].puzzleImage,name:t(lang,'Bitkisel çizim','Planting drawing'),href:projects[0].route},
  {src:projects[2].image,name:t(lang,'Ortak yaşam','Shared living'),href:projects[2].route},
  {src:'assets/sketches/landscape-assembly.webp',name:t(lang,'Bir düşüncenin parçaları','Fragments of a thought'),href:'#about'},
  {src:projects[4].puzzleImage,name:t(lang,'Yapının içinden','Inside the structure'),href:projects[4].route}
 ];
 return `<section class="studio-desk" id="studio"><header class="studio-heading"><div><span class="ink-note">${t(lang,'Çalışma masası','The studio desk')}</span><h2>${t(lang,'Biraz merak.<br><em>Bir sürü bağlantı.</em>','A little curiosity.<br><em>A lot of connections.</em>')}</h2><p id="desk-help">${t(lang,'Parçaları hareket ettir. Merakının peşinden git. Klavyeyle: ok tuşları.','Move things around. Follow your curiosity. Keyboard: arrow keys.')}</p></div><button class="desk-reset">${t(lang,'Masayı düzenle','Reset desk')} ↺</button></header><div class="scrap-surface">${scraps.map((s,i)=>`<article class="desk-scrap scrap-${i}" data-scrap="${i}"><button class="scrap-grip" aria-describedby="desk-help" aria-label="${t(lang,'Parçayı taşı: ','Move scrap: ')}${s.name}"><span>0${i+1}</span> ${s.name}<span aria-hidden="true">⠿</span></button><img src="${s.src}" alt="${s.name}" loading="lazy" draggable="false"><a href="${s.href}">${t(lang,'Biraz daha yakından','Take a closer look')} ↗</a></article>`).join('')}<span class="desk-whisper" aria-hidden="true">${t(lang,'Hepsi birbirine bağlı.','All connected.')}</span></div><div class="paper-ribbon"><span>${t(lang,'Çiz','Draw')}</span><i></i><span>${t(lang,'Birleştir','Assemble')}</span><i></i><span>${t(lang,'Keşfet','Discover')}</span></div></section>`;
}
export function projectLab(p,lang,base){
 const plan=base+p.puzzleImage,render=base+p.image;
 return `<section class="project-lab" id="explore" data-lab="${p.id}"><header class="lab-heading"><span class="ink-note">${t(lang,'Bakmanın başka yolları','Other ways of seeing')}</span><h2>${t(lang,'Çizginin<br><em>öteki tarafı.</em>','The other side<br><em>of the line.</em>')}</h2><p>${t(lang,'Çizim ve görselleştirme arasında gezinerek projeye iki farklı açıdan bak.','Slide between drawing and visualization to explore two different views of the project.')}</p></header><div class="drawing-viewer" style="--reveal:50%" tabindex="0" aria-label="${t(lang,'Çizim inceleme alanı. Büyüteç açıkken ok tuşlarıyla gezin.','Drawing viewer. Use arrow keys to move when the lens is enabled.')}"><img class="study-under" src="${render}" alt="${title(p,lang)} — ${t(lang,'görselleştirme','visualization')}" loading="lazy"><div class="study-overlay"><img src="${plan}" alt="${title(p,lang)} — ${t(lang,'çizim','drawing')}" loading="lazy"></div><div class="study-divider" aria-hidden="true"><span>↔</span></div><div class="detail-lens" aria-hidden="true" style="background-image:url('${plan}')"></div><span class="view-label view-left">${t(lang,'Çizim','Drawing')}</span><span class="view-label view-right">${t(lang,'Görselleştirme','Visualization')}</span></div><div class="viewer-controls"><label>${t(lang,'Çizimi açığa çıkar','Reveal the drawing')}<input class="reveal-range" type="range" min="0" max="100" value="50"></label><button class="lens-toggle" aria-pressed="false">${t(lang,'Çizim büyüteci','Drawing lens')} +</button><a href="${plan}" target="_blank" rel="noopener">${t(lang,'Orijinali aç','Open original')} ↗</a></div><p class="lens-help">${t(lang,'Büyüteç: çizime dokun veya üzerinde gezin. Ok tuşlarıyla da hareket ettirebilirsin.','Lens: tap or move over the drawing. Arrow keys also move the lens.')}</p><div class="tracing-controls"><span>${t(lang,'Aydınger masası','Tracing table')}</span><button data-layer="plan" aria-pressed="true">${t(lang,'Çizim','Drawing')}</button><button data-layer="board" aria-pressed="false">${t(lang,'Pafta','Board')}</button><label>${t(lang,'Kâğıt opaklığı','Paper opacity')}<input class="paper-opacity" type="range" min="15" max="100" value="100"></label></div><section class="process-study"><header><h3>${t(lang,'Fikrin izini sür.','Follow the idea.')}</h3><p>${t(lang,'Çizim, görselleştirme ve orijinal portfolyo paftaları.','Drawing, visualization and original portfolio boards.')}</p></header><figure><img class="process-image" src="${plan}" alt="${title(p,lang)}" loading="lazy"><figcaption class="process-caption" aria-live="polite">${t(lang,'Çizim','Drawing')}</figcaption></figure><div class="process-navigation"><button class="process-prev" aria-label="${t(lang,'Önceki görsel','Previous image')}">←</button><label>${t(lang,'Görseller arasında gezin','Browse the studies')}<input class="process-range" type="range" min="0" max="${p.pages.length+1}" value="0" step="1"></label><button class="process-next" aria-label="${t(lang,'Sonraki görsel','Next image')}">→</button><output class="process-count">01 / ${String(p.pages.length+2).padStart(2,'0')}</output></div></section></section>${p.id==='canteen'?modelTable(p,lang,base):''}`;
}
function modelTable(p,lang,base){return `<section class="model-table"><header><span class="ink-note">${t(lang,'Biraz perspektif','A little perspective')}</span><h2>${t(lang,'Mekâna yaklaş.','Lean into the place.')}</h2><p>${t(lang,'Mevcut proje görselleştirmesinden etkileşimli bir görünüm. Görseli eğ veya bir ayrıntıyı seç.','An interactive view of the existing project visualization. Tilt the image or choose a detail.')}</p></header><div class="model-stage"><div class="model-plane"><img src="${base+p.image}" alt="${title(p,lang)}" loading="lazy">${[[30,35],[55,58],[78,70]].map(([x,y],i)=>`<button class="model-pin" style="left:${x}%;top:${y}%" data-x="${x}" data-y="${y}" aria-label="${t(lang,'Ayrıntı','Detail')} ${i+1}" aria-pressed="false">0${i+1}</button>`).join('')}</div></div><div class="model-controls"><label>${t(lang,'Bakış açısı','Viewing angle')}<input class="model-angle" type="range" min="-12" max="12" value="0"></label><button class="model-reset">${t(lang,'Görünümü sıfırla','Reset view')} ↺</button></div><div class="model-detail" hidden><img src="${base+p.image}" alt="${t(lang,'Seçilen görselleştirme ayrıntısı','Selected visualization detail')}" loading="lazy"><span aria-live="polite"></span></div></section>`;}
